package com.barrageindicator;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.List;
import net.runelite.api.CollisionDataFlag;
import org.junit.Test;

/**
 * One mark per tile: with monsters of different sizes on the same south-west tile, the counts on it can differ
 * (the large one sees from more tiles). The tile keeps the largest count, and is the best if any of them is.
 */
public class OneMarkPerTileTest
{
	@Test
	public void theBestMarkNeverGoesAway() throws Exception
	{
		// a 1x1 and a 2x2 on (50,50), the 1x1 first in the client's list; scenery on (50,49);
		// a 1x1 on (49,49) and another on (51,49). Found by searching every such arrangement.
		TestWorld w = new TestWorld();
		w.flags[50][49] |= CollisionDataFlag.BLOCK_LINE_OF_SIGHT_FULL;
		w.add("Kalphite Worker", 50, 50, 1);
		w.add("Kalphite Soldier", 50, 50, 2);
		w.add("Kalphite Worker", 49, 49, 1);
		w.add("Kalphite Worker", 51, 49, 1);
		List<BarrageIndicatorPlugin.Pile> piles = w.run();
		String s = TestWorld.show(piles);
		BarrageIndicatorPlugin.Pile middle = TestWorld.at(piles, 50, 50);
		assertEquals(s, 4, middle.hits);
		assertTrue(s, middle.best);
		assertEquals(s, 3, TestWorld.at(piles, 49, 49).hits);
		assertFalse(s, TestWorld.at(piles, 49, 49).best);
		assertEquals(s, 3, piles.size());
	}

	@Test
	public void sameTileSameSizeIsOneMark() throws Exception
	{
		TestWorld w = new TestWorld();
		w.addMany("Smoke devil", 50, 50, 5);
		List<BarrageIndicatorPlugin.Pile> piles = w.run();
		assertEquals(TestWorld.show(piles), 1, piles.size());
	}
}

package com.barrageindicator;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import java.util.List;
import org.junit.Test;

/**
 * "Count monsters not on task": the spell hits every monster it can attack, up to nine (Death spawn among the
 * Greater Nechryael take up some of the nine). Off by default: only the task's monsters are counted, as before.
 * On: the others count too, and the marks stay on monsters of the task.
 */
public class OtherMonstersTest
{
	private static TestWorld nechryael(boolean countOthers)
	{
		TestWorld w = new TestWorld();
		w.onlyTask = true;
		w.countOthers = countOthers;
		w.task = "Nechryael";
		w.taskLeft = 150;
		for (int i = 0; i < 5; i++)
		{
			w.add("Death spawn", 50, 50, 1);
		}
		w.addMany("Greater Nechryael", 50, 50, 4);
		w.addMany("Greater Nechryael", 60, 60, 6);
		w.addMany("Death spawn", 70, 70, 9);
		return w;
	}

	@Test
	public void offByDefault()
	{
		assertFalse(new BarrageIndicatorConfig()
		{
		}.countOthers());
	}

	@Test
	public void offOnlyTheTaskCounts() throws Exception
	{
		List<BarrageIndicatorPlugin.Pile> piles = nechryael(false).run();
		String s = TestWorld.show(piles);
		assertEquals(s, 4, TestWorld.at(piles, 50, 50).hits);
		assertTrue(s, TestWorld.at(piles, 60, 60).best);
		assertNull(s, TestWorld.at(piles, 70, 70));
	}

	@Test
	public void onTheOthersCountAndTheMarksStayOnTheTask() throws Exception
	{
		List<BarrageIndicatorPlugin.Pile> piles = nechryael(true).run();
		String s = TestWorld.show(piles);
		BarrageIndicatorPlugin.Pile mixed = TestWorld.at(piles, 50, 50);
		assertEquals(s, 9, mixed.hits);
		assertTrue(s, mixed.best);
		assertEquals("Greater Nechryael", mixed.npc.getName());
		assertEquals(s, 6, TestWorld.at(piles, 60, 60).hits);
		assertFalse(s, TestWorld.at(piles, 60, 60).best);
		assertNull("a pile of Death spawn alone is never marked " + s, TestWorld.at(piles, 70, 70));
	}
}

package com.barrageindicator;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;

public class PileCalcTest
{
	private static PileCalc.Spot at(int x, int y)
	{
		return new PileCalc.Spot(x, y, 1);
	}

	@Test
	public void aLoneMonsterIsHitAlone()
	{
		assertArrayEquals(new int[]{1}, PileCalc.hits(Arrays.asList(at(10, 10))));
	}

	@Test
	public void sameTileAndNeighboursCount()
	{
		// three on one tile, one diagonal to it, one two tiles away
		List<PileCalc.Spot> spots = Arrays.asList(at(10, 10), at(10, 10), at(10, 10), at(11, 11), at(12, 10));
		assertArrayEquals(new int[]{4, 4, 4, 5, 2}, PileCalc.hits(spots));
	}

	@Test
	public void theMiddleOfALineHitsMore()
	{
		List<PileCalc.Spot> spots = Arrays.asList(at(10, 10), at(11, 10), at(12, 10));
		assertArrayEquals(new int[]{2, 3, 2}, PileCalc.hits(spots));
	}

	@Test
	public void neverMoreThanNine()
	{
		List<PileCalc.Spot> spots = new ArrayList<>();
		for (int i = 0; i < 14; i++)
		{
			spots.add(at(10, 10));
		}
		assertEquals(9, PileCalc.hits(spots)[0]);
	}

	@Test
	public void aLargeMonsterCountsByItsSouthWestTileAlone()
	{
		PileCalc.Spot small = at(10, 10);
		// a 3x3 monster whose south-west tile is next to (10,10) is hit; one whose body only reaches the area is not
		assertTrue(PileCalc.inArea(small, new PileCalc.Spot(11, 11, 3)));
		assertFalse(PileCalc.inArea(small, new PileCalc.Spot(12, 12, 3)));
		assertFalse(PileCalc.inArea(small, new PileCalc.Spot(8, 8, 3)));
		// two 2x2 monsters side by side: their south-west tiles are two apart, so neither cast hits the other
		PileCalc.Spot left = new PileCalc.Spot(20, 20, 2);
		PileCalc.Spot right = new PileCalc.Spot(22, 20, 2);
		assertFalse(PileCalc.inArea(left, right));
		assertFalse(PileCalc.inArea(right, left));
		// overlapping by a tile, they are
		assertTrue(PileCalc.inArea(left, new PileCalc.Spot(21, 21, 2)));
	}

	@Test
	public void taskNamesMatchTheirMonsters()
	{
		assertTrue(PileCalc.matches("Smoke devil", "Smoke devils", ""));
		assertTrue(PileCalc.matches("Greater Nechryael", "Nechryael", ""));
		assertTrue(PileCalc.matches("Abyssal demon", "Abyssal demons", ""));
		assertTrue(PileCalc.matches("Dust devil", "Dust devils", ""));
		assertTrue(PileCalc.matches("Ankou", "Ankou", ""));
		assertFalse(PileCalc.matches("Ankou", "Dust devils", ""));
		assertFalse(PileCalc.matches("Smoke devil", null, ""));
		assertTrue(PileCalc.matches("Deviant spectre", "Dust devils", "spectre, kurask"));
		assertEquals("abyss", PileCalc.singular("Abyss"));
	}

	@Test
	public void theIconIsTheSpellOnAutocast()
	{
		assertEquals(net.runelite.api.SpriteID.SPELL_BLOOD_BARRAGE, BarrageIndicatorPlugin.spellSprite(45));
		assertEquals(net.runelite.api.SpriteID.SPELL_ICE_BURST, BarrageIndicatorPlugin.spellSprite(38));
		assertEquals(net.runelite.api.SpriteID.SPELL_ICE_BARRAGE, BarrageIndicatorPlugin.spellSprite(46));
		assertEquals(net.runelite.api.SpriteID.SPELL_ICE_BARRAGE, BarrageIndicatorPlugin.spellSprite(0));
	}

	@Test
	public void aMonsterTheTargetCannotSeeIsNotCounted()
	{
		List<PileCalc.Spot> spots = new ArrayList<>();
		spots.add(at(10, 10));
		spots.add(at(11, 10));
		spots.add(at(9, 10));
		// the middle one sees both; the two at the ends have something between them
		int[] hits = PileCalc.hits(spots, (target, other) -> !(target == 1 && other == 2) && !(target == 2 && other == 1));
		assertEquals(3, hits[0]);
		assertEquals(2, hits[1]);
		assertEquals(2, hits[2]);
	}
}

package com.barrageindicator;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import java.util.List;
import net.runelite.api.CollisionDataFlag;
import net.runelite.api.coords.WorldArea;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

/** The plugin's whole path, one game tick at a time, with RuneLite's real line of sight. */
public class PluginPathTest
{
	@Test
	public void realSightOnOpenGround()
	{
		// what the plugin relies on: the jar's line of sight sees a neighbour on open ground, not through a wall,
		// and says "no" between areas that overlap
		TestWorld w = new TestWorld();
		WorldArea a = new WorldArea(new WorldPoint(TestWorld.BASE_X + 50, TestWorld.BASE_Y + 50, 0), 1, 1);
		WorldArea same = new WorldArea(new WorldPoint(TestWorld.BASE_X + 50, TestWorld.BASE_Y + 50, 0), 1, 1);
		WorldArea east = new WorldArea(new WorldPoint(TestWorld.BASE_X + 51, TestWorld.BASE_Y + 50, 0), 1, 1);
		WorldArea diagonal = new WorldArea(new WorldPoint(TestWorld.BASE_X + 49, TestWorld.BASE_Y + 49, 0), 1, 1);
		assertTrue(!a.hasLineOfSightTo(w.view, same));
		assertTrue(a.hasLineOfSightTo(w.view, east));
		assertTrue(a.hasLineOfSightTo(w.view, diagonal));
		w.flags[51][50] |= CollisionDataFlag.BLOCK_LINE_OF_SIGHT_WEST;
		assertTrue(!a.hasLineOfSightTo(w.view, east));
	}

	@Test
	public void aWallBetweenTwoMonstersKeepsThemApart() throws Exception
	{
		TestWorld open = new TestWorld();
		open.add("Smoke devil", 50, 50, 1);
		open.add("Smoke devil", 51, 50, 1);
		List<BarrageIndicatorPlugin.Pile> piles = open.run();
		assertEquals(TestWorld.show(piles), 2, piles.size());
		assertEquals(2, piles.get(0).hits);

		TestWorld walled = new TestWorld();
		walled.flags[51][50] |= CollisionDataFlag.BLOCK_LINE_OF_SIGHT_WEST;
		walled.flags[50][50] |= CollisionDataFlag.BLOCK_LINE_OF_SIGHT_EAST;
		walled.add("Smoke devil", 50, 50, 1);
		walled.add("Smoke devil", 51, 50, 1);
		assertTrue("each one alone, below the smallest pile", walled.run().isEmpty());
	}

	@Test
	public void deadMonstersAreLeftOut() throws Exception
	{
		TestWorld w = new TestWorld();
		w.addMany("Smoke devil", 50, 50, 3);
		for (int i = 0; i < 3; i++)
		{
			w.add("Smoke devil", 50, 50, 1, true);
		}
		List<BarrageIndicatorPlugin.Pile> piles = w.run();
		assertEquals(TestWorld.show(piles), 1, piles.size());
		assertEquals(3, piles.get(0).hits);
	}

	@Test
	public void neverMoreThanNine() throws Exception
	{
		TestWorld w = new TestWorld();
		w.addMany("Smoke devil", 50, 50, 14);
		List<BarrageIndicatorPlugin.Pile> piles = w.run();
		assertEquals(TestWorld.show(piles), 1, piles.size());
		assertEquals(9, piles.get(0).hits);
	}

	@Test
	public void onlyTheTaskMonstersCount() throws Exception
	{
		TestWorld w = new TestWorld();
		w.onlyTask = true;
		w.task = "Smoke devils";
		w.taskLeft = 40;
		w.addMany("Smoke devil", 50, 50, 3);
		w.addMany("Skeleton", 50, 50, 3);
		List<BarrageIndicatorPlugin.Pile> piles = w.run();
		assertEquals(TestWorld.show(piles), 1, piles.size());
		assertEquals(3, piles.get(0).hits);
		assertEquals("Smoke devil", piles.get(0).npc.getName());
	}

	@Test
	public void withoutATaskNothingIsDrawn() throws Exception
	{
		TestWorld w = new TestWorld();
		w.onlyTask = true;
		w.task = "Smoke devils";
		w.taskLeft = 0;
		w.addMany("Smoke devil", 50, 50, 3);
		assertTrue(w.run().isEmpty());

		// the extra names still work without a task
		w.extraNames = "smoke";
		assertEquals(3, w.run().get(0).hits);
	}

	@Test
	public void onlyOnAncientsAndInMulti() throws Exception
	{
		TestWorld w = new TestWorld();
		w.addMany("Smoke devil", 50, 50, 3);
		w.onlyAncients = true;
		w.spellbook = 0;
		assertTrue(w.run().isEmpty());
		w.spellbook = 1;
		assertEquals(1, w.run().size());
		w.onlyMulti = true;
		w.multi = 0;
		assertTrue(w.run().isEmpty());
		w.multi = 1;
		assertEquals(1, w.run().size());
	}

	@Test
	public void smallerPilesThanTheSmallestAreNotDrawn() throws Exception
	{
		TestWorld w = new TestWorld();
		w.minimum = 4;
		w.addMany("Smoke devil", 50, 50, 3);
		w.addMany("Smoke devil", 60, 60, 5);
		List<BarrageIndicatorPlugin.Pile> piles = w.run();
		assertNull(TestWorld.show(piles), TestWorld.at(piles, 50, 50));
		assertNotNull(TestWorld.at(piles, 60, 60));
		assertEquals(5, TestWorld.at(piles, 60, 60).hits);
	}
}

package com.barrageindicator;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.List;
import net.runelite.api.CollisionDataFlag;
import org.junit.Test;

/**
 * The best pile is the best one the player can cast on without walking: within the spell's range and in line of
 * sight from the player. OSRS Wiki, Attack range (read 2026-10-15): combat spells reach 10 squares, measured as
 * Chebyshev distance; Line of sight: for a monster larger than one tile, the tile closest to the player counts.
 * With none in reach, the largest pile of all.
 */
public class ReachTest
{
	@Test
	public void aPileOutOfRangeIsNotTheBest() throws Exception
	{
		// another player's pile 15 tiles away (Greater Nechryael): the best is the one in reach
		TestWorld w = new TestWorld();
		w.player(50, 50);
		w.addMany("Greater Nechryael", 55, 50, 5);
		w.addMany("Greater Nechryael", 65, 50, 8);
		List<BarrageIndicatorPlugin.Pile> piles = w.run();
		String s = TestWorld.show(piles);
		assertTrue(s, TestWorld.at(piles, 55, 50).best);
		assertEquals(s, 8, TestWorld.at(piles, 65, 50).hits);
		assertFalse(s, TestWorld.at(piles, 65, 50).best);
	}

	@Test
	public void tenTilesIsInRangeElevenIsNot() throws Exception
	{
		TestWorld w = new TestWorld();
		w.player(50, 50);
		w.addMany("Smoke devil", 60, 57, 3);
		w.addMany("Smoke devil", 61, 50, 6);
		List<BarrageIndicatorPlugin.Pile> piles = w.run();
		String s = TestWorld.show(piles);
		assertTrue(s, TestWorld.at(piles, 60, 57).best);
		assertFalse(s, TestWorld.at(piles, 61, 50).best);
	}

	@Test
	public void aLargeMonsterIsMeasuredToItsClosestTile() throws Exception
	{
		// three 2x2 piled up west of the player; the middle one's south-west tile (39,50) is 11 away,
		// but its body reaches (40,50), 10 away: in range
		TestWorld w = new TestWorld();
		w.player(50, 50);
		w.add("Araxyte", 38, 50, 2);
		w.add("Araxyte", 39, 50, 2);
		w.add("Araxyte", 40, 50, 2);
		w.addMany("Araxyte", 50, 55, 2);
		List<BarrageIndicatorPlugin.Pile> piles = w.run();
		String s = TestWorld.show(piles);
		assertEquals(s, 3, TestWorld.at(piles, 39, 50).hits);
		assertTrue(s, TestWorld.at(piles, 39, 50).best);
		assertFalse(s, TestWorld.at(piles, 50, 55).best);

		TestWorld far = new TestWorld();
		far.player(50, 50);
		far.add("Araxyte", 60, 39, 2);
		far.add("Araxyte", 61, 39, 2);
		far.add("Araxyte", 62, 39, 2);
		far.addMany("Araxyte", 50, 45, 2);
		piles = far.run();
		s = TestWorld.show(piles);
		// (61,39): its closest tile is (61,40), 11 away in x: out of range, though it is the largest
		assertEquals(s, 3, TestWorld.at(piles, 61, 39).hits);
		assertFalse(s, TestWorld.at(piles, 61, 39).best);
		assertTrue(s, TestWorld.at(piles, 50, 45).best);
	}

	@Test
	public void aPileBehindAWallIsNotTheBest() throws Exception
	{
		TestWorld w = new TestWorld();
		w.player(50, 50);
		// a wall on the tile east of the player, from the ground up: no sight to the east pile
		w.flags[51][50] |= CollisionDataFlag.BLOCK_LINE_OF_SIGHT_FULL | CollisionDataFlag.BLOCK_MOVEMENT_FULL;
		w.addMany("Smoke devil", 54, 50, 8);
		w.addMany("Smoke devil", 50, 54, 4);
		List<BarrageIndicatorPlugin.Pile> piles = w.run();
		String s = TestWorld.show(piles);
		assertEquals(s, 8, TestWorld.at(piles, 54, 50).hits);
		assertFalse(s, TestWorld.at(piles, 54, 50).best);
		assertTrue(s, TestWorld.at(piles, 50, 54).best);
	}

	@Test
	public void withNoPileInReachTheLargestIsMarked() throws Exception
	{
		TestWorld w = new TestWorld();
		w.player(10, 10);
		w.addMany("Smoke devil", 50, 50, 3);
		w.addMany("Smoke devil", 70, 70, 6);
		List<BarrageIndicatorPlugin.Pile> piles = w.run();
		String s = TestWorld.show(piles);
		assertTrue(s, TestWorld.at(piles, 70, 70).best);
		assertFalse(s, TestWorld.at(piles, 50, 50).best);
	}

	@Test
	public void aPileTooSmallToDrawDoesNotCountAsInReach() throws Exception
	{
		// the only monster in reach is alone (below the smallest pile): the largest pile is marked
		TestWorld w = new TestWorld();
		w.player(50, 50);
		w.add("Smoke devil", 52, 50, 1);
		w.addMany("Smoke devil", 70, 70, 4);
		List<BarrageIndicatorPlugin.Pile> piles = w.run();
		assertTrue(TestWorld.show(piles), TestWorld.at(piles, 70, 70).best);
	}
}

