	@Test
	public void withNothingWrittenItSaysSo()
	{
		assertTrue(ReportWindow.body("  ", null).contains("(nothing written)"));
	}

	@Test
	public void theLinkOpensANewIssueOnThePluginsRepositoryAndFitsInALink()
	{
		StringBuilder longBody = new StringBuilder();
		for (int i = 0; i < 900; i++)
		{
			longBody.append("a line of it\n");
		}
		String link = ReportWindow.link("wrong & odd", longBody.toString());
		assertTrue(link.startsWith("https://github.com/" + ReportWindow.REPOSITORY + "/issues/new?title=wrong%20%26%20odd&body="));
		assertTrue(link.contains("Cut%20short"));
		assertTrue(link.length() < 12000);
		assertEquals(-1, link.indexOf(' '));
	}
}

package com.barrageindicator;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import java.util.List;
import net.runelite.api.CollisionDataFlag;
import org.junit.Test;

/**
 * Monsters on the same tile (areas on top of each other) are hit together. RuneLite's line of sight says
 * "no sight" between areas that overlap, so the plugin has to count those itself. Whole path of the plugin,
 * real line of sight.
 */
public class SameTileTest
{
	@Test
	public void nineOnOneTileCountNine() throws Exception
	{
		TestWorld w = new TestWorld();
		w.addMany("Smoke devil", 50, 50, 9);
		List<BarrageIndicatorPlugin.Pile> piles = w.run();
		assertEquals(TestWorld.show(piles), 1, piles.size());
		assertEquals(9, piles.get(0).hits);
		assertTrue(piles.get(0).best);
	}

	@Test
	public void aPileOfSixBeatsFourSpreadOut() throws Exception
	{
		TestWorld w = new TestWorld();
		w.addMany("Smoke devil", 50, 50, 6);
		w.add("Smoke devil", 60, 60, 1);
		w.add("Smoke devil", 61, 60, 1);
		w.add("Smoke devil", 60, 61, 1);
		w.add("Smoke devil", 61, 61, 1);
		List<BarrageIndicatorPlugin.Pile> piles = w.run();
		BarrageIndicatorPlugin.Pile six = TestWorld.at(piles, 50, 50);
		assertNotNull(TestWorld.show(piles), six);
		assertEquals(6, six.hits);
		assertTrue(six.best);
		for (BarrageIndicatorPlugin.Pile p : piles)
		{
			if (p != six)
			{
				assertEquals(4, p.hits);
				assertFalse(p.best);
			}
		}
	}

	@Test
	public void pilesOfFiveTwoAndTwoAroundThePlayer() throws Exception
	{
		// north x5, west x2, east x2: a cast on the north pile hits all 9, one on a side pile 7
		TestWorld w = new TestWorld();
		w.addMany("Greater Nechryael", 50, 51, 5);
		w.addMany("Greater Nechryael", 49, 50, 2);
		w.addMany("Greater Nechryael", 51, 50, 2);
		List<BarrageIndicatorPlugin.Pile> piles = w.run();
		String s = TestWorld.show(piles);
		assertEquals(s, 9, TestWorld.at(piles, 50, 51).hits);
		assertTrue(s, TestWorld.at(piles, 50, 51).best);
		assertEquals(s, 7, TestWorld.at(piles, 49, 50).hits);
		assertFalse(s, TestWorld.at(piles, 49, 50).best);
		assertEquals(s, 7, TestWorld.at(piles, 51, 50).hits);
		assertFalse(s, TestWorld.at(piles, 51, 50).best);
	}

	@Test
	public void threeLargeMonstersOnTopOfEachOther() throws Exception
	{
		// three 2x2 with south-west tiles one apart (araxytes, hellhounds): each cast hits the three
		TestWorld w = new TestWorld();
		w.add("Araxyte", 50, 50, 2);
		w.add("Araxyte", 51, 50, 2);
		w.add("Araxyte", 50, 51, 2);
		List<BarrageIndicatorPlugin.Pile> piles = w.run();
		assertEquals(TestWorld.show(piles), 3, piles.size());
		for (BarrageIndicatorPlugin.Pile p : piles)
		{
			assertEquals(3, p.hits);
			assertTrue(p.best);
		}
	}

	/** The bones of the Smoke Devil Dungeon on (50,50), blocking sight, and smoke devils on each side. */
	private static TestWorld bones(int north, int east, int south, int west)
	{
		TestWorld w = new TestWorld();
		w.flags[50][50] |= CollisionDataFlag.BLOCK_LINE_OF_SIGHT_FULL | CollisionDataFlag.BLOCK_MOVEMENT_FULL;
		w.addMany("Smoke devil", 50, 51, north);
		w.addMany("Smoke devil", 51, 50, east);
		w.addMany("Smoke devil", 50, 49, south);
		w.addMany("Smoke devil", 49, 50, west);
		return w;
	}

	@Test
	public void sightRoundTheBonesStaysOneWay() throws Exception
	{
		// seen in game (2026-10-12): cast on the east one, the north one is hit; cast on the north one, the east one is not
		TestWorld w = bones(1, 1, 0, 0);
		List<BarrageIndicatorPlugin.Pile> piles = w.run();
		String s = TestWorld.show(piles);
		assertEquals(s, 2, TestWorld.at(piles, 51, 50).hits);
		assertNull("a cast on the north one hits it alone: below the smallest pile, not drawn " + s, TestWorld.at(piles, 50, 51));
	}

	@Test
	public void pilesRoundTheBones() throws Exception
	{
		// north 3, east 2, south 3, west 2: east and west see north and south, not the other way round
		TestWorld w = bones(3, 2, 3, 2);
		List<BarrageIndicatorPlugin.Pile> piles = w.run();
		String s = TestWorld.show(piles);
		assertEquals(s, 8, TestWorld.at(piles, 51, 50).hits);
		assertEquals(s, 8, TestWorld.at(piles, 49, 50).hits);
		assertEquals(s, 3, TestWorld.at(piles, 50, 51).hits);
		assertEquals(s, 3, TestWorld.at(piles, 50, 49).hits);
		assertTrue(TestWorld.at(piles, 51, 50).best);
		assertTrue(TestWorld.at(piles, 49, 50).best);
		assertFalse(TestWorld.at(piles, 50, 51).best);
	}
}

package com.barrageindicator;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.List;
import org.junit.Test;

/**
 * Task names that are not a plain plural of their monsters find the right monsters, and only them.
 * Monster names from the OSRS Wiki pages Slayer task/<task> (read 2026-10-15).
 */
public class TaskNameTest
{
	private static void finds(String task, String... monsters)
	{
		for (String m : monsters)
		{
			assertTrue(m + " is on the task " + task, PileCalc.matches(m, task, ""));
		}
	}

	private static void skips(String task, String... monsters)
	{
		for (String m : monsters)
		{
			assertFalse(m + " is not on the task " + task, PileCalc.matches(m, task, ""));
		}
	}

	@Test
	public void irregularTaskNames()
	{
		finds("Jellies", "Jelly", "Warped jelly", "Chilled jelly", "Vitreous Jelly", "Vitreous Warped Jelly", "Vitreous Chilled Jelly");
		finds("Lizardmen", "Lizardman", "Lizardman shaman", "Lizardman brute");
		finds("Elves", "Elf Warrior", "Elf Archer", "Iorwerth Warrior", "Iorwerth Archer", "Reanimated elf");
		finds("Spiritual creatures", "Spiritual ranger", "Spiritual mage", "Spiritual warrior");
		finds("Aberrant spectres", "Aberrant spectre", "Abhorrent spectre", "Deviant spectre", "Repugnant spectre");
		finds("Fossil island wyverns", "Ancient Wyvern", "Long-tailed Wyvern", "Spitting Wyvern", "Taloned Wyvern");
		finds("Wolves", "Big Wolf", "Desert Wolf", "Dire Wolf", "Ice wolf", "Jungle wolf");
		finds("Dwarves", "Dwarf", "Chaos dwarf", "Black Guard", "Black Guard Berserker", "Dwarf gang member");
		finds("Warped Creatures", "Warped Terrorbird", "Warped Tortoise", "Mutated Terrorbird", "Mutated Tortoise");
		// the superior ones
		finds("Dust devils", "Dust devil", "Choke devil");
		finds("Nechryael", "Nechryael", "Greater Nechryael", "Nechryarch");
	}

	@Test
	public void onlyThoseMonsters()
	{
		skips("Elves", "Skeleton", "Shelob");
		skips("Wolves", "Werewolf");
		skips("Fossil island wyverns", "Skeletal Wyvern");
		skips("Nechryael", "Death spawn");
		skips("Jellies", "Smoke devil");
		skips("Smoke devils", "Jelly");
	}

	@Test
	public void plainPluralsStillWork()
	{
		finds("Smoke devils", "Smoke devil", "Nuclear smoke devil");
		finds("Abyssal demons", "Abyssal demon", "Greater abyssal demon");
		finds("Kalphites", "Kalphite Worker", "Kalphite Soldier");
		finds("Tzhaar", "TzHaar-Ket", "TzHaar-Xil");
		finds("Ankou", "Ankou");
		finds("Hellhounds", "Hellhound");
		skips("Dust devils", "Ankou");
	}

	@Test
	public void aJelliesTaskOnTheWholePath() throws Exception
	{
		TestWorld w = new TestWorld();
		w.onlyTask = true;
		w.task = "Jellies";
		w.taskLeft = 120;
		w.addMany("Warped jelly", 50, 50, 4);
		w.addMany("Skeleton", 50, 50, 3);
		List<BarrageIndicatorPlugin.Pile> piles = w.run();
		assertEquals(TestWorld.show(piles), 1, piles.size());
		assertEquals(4, piles.get(0).hits);
	}

	@Test
	public void anElvesTaskLeavesSkeletonsOut() throws Exception
	{
		TestWorld w = new TestWorld();
		w.onlyTask = true;
		w.task = "Elves";
		w.taskLeft = 120;
		w.addMany("Skeleton", 50, 50, 5);
		assertTrue(TestWorld.show(w.run()), w.run().isEmpty());
		w.addMany("Iorwerth Warrior", 60, 60, 3);
		List<BarrageIndicatorPlugin.Pile> piles = w.run();
		assertEquals(TestWorld.show(piles), 1, piles.size());
		assertEquals("Iorwerth Warrior", piles.get(0).npc.getName());
	}
}

package com.barrageindicator;

import java.lang.reflect.Field;
import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Function;
import net.runelite.api.Client;
import net.runelite.api.CollisionData;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.IndexedObjectSet;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.Player;
import net.runelite.api.Scene;
import net.runelite.api.Tile;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldArea;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameTick;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;

/**
 * A fake game for the plugin's whole path (onGameTick -> work() -> PileCalc), with RuneLite's real
 * WorldArea.hasLineOfSightTo: a 104x104 scene on plane 0 with real tiles and editable collision flags
 * (open ground = 0), the client, the local player and the monsters, all as plain proxies.
 * Monsters behave like the injected client: getWorldArea() = new WorldArea(getWorldLocation(), size, size).
 * Coordinates given to it are scene coordinates; the world ones are BASE_X/BASE_Y further.
 */
final class TestWorld
{
	static final int BASE_X = 3200;
	static final int BASE_Y = 3200;

	final int[][] flags = new int[104][104];
	final List<NPC> npcs = new ArrayList<>();
	final WorldView view;

	/** Plugin settings, the plugin's defaults except the three context filters. */
	boolean onlyTask = false;
	boolean countOthers = false;
	boolean onlyAncients = false;
	boolean onlyMulti = false;
	String extraNames = "";
	int minimum = 2;

	/** Game state read by the plugin. */
	int spellbook = 1;
	int multi = 1;
	int taskLeft = 0;
	String task = null;
	/** The item in the weapon slot (-1: none) and the attack style setting (3: long fuse). */
	int weapon = -1;
	int attackStyle = 0;
	private Player player;
	/** The plugin of the last run(), to read what it keeps for the overlay. */
	BarrageIndicatorPlugin lastPlugin;

	TestWorld()
	{
		Tile[][][] tiles = new Tile[4][104][104];
		for (int z = 0; z < 4; z++)
		{
			for (int x = 0; x < 104; x++)
			{
				for (int y = 0; y < 104; y++)
				{
					final int fz = z, fx = x, fy = y;
					Map<String, Function<Object[], Object>> t = new HashMap<>();
					t.put("getPlane", a -> fz);
					t.put("getSceneLocation", a -> new net.runelite.api.Point(fx, fy));
					t.put("getWorldLocation", a -> new WorldPoint(BASE_X + fx, BASE_Y + fy, fz));
					tiles[z][x][y] = proxy(Tile.class, t);
				}
			}
		}
		Map<String, Function<Object[], Object>> c = new HashMap<>();
		c.put("getFlags", a -> flags);
		CollisionData cd = proxy(CollisionData.class, c);
		CollisionData[] maps = {cd, cd, cd, cd};
		Map<String, Function<Object[], Object>> s = new HashMap<>();
		s.put("getTiles", a -> tiles);
		Scene scene = proxy(Scene.class, s);
		Map<String, Function<Object[], Object>> set = new HashMap<>();
		set.put("iterator", a -> npcs.iterator());
		@SuppressWarnings("unchecked")
		IndexedObjectSet<NPC> npcSet = proxy(IndexedObjectSet.class, set);
		Map<String, Function<Object[], Object>> v = new HashMap<>();
		v.put("getScene", a -> scene);
		v.put("getCollisionMaps", a -> maps);
		v.put("getPlane", a -> 0);
		v.put("getBaseX", a -> BASE_X);
		v.put("getBaseY", a -> BASE_Y);
		v.put("getSizeX", a -> 104);
		v.put("getSizeY", a -> 104);
		v.put("getId", a -> -1);
		v.put("isTopLevel", a -> true);
		v.put("npcs", a -> npcSet);
		view = proxy(WorldView.class, v);
	}

	/** A monster whose south-west tile is (x,y) of the scene; it goes at the end of the client's list. */
	NPC add(String name, int x, int y, int size)
	{
		return add(name, x, y, size, false);
	}

	NPC add(String name, int x, int y, int size, boolean dead)
	{
		Map<String, Function<Object[], Object>> comp = new HashMap<>();
		comp.put("getActions", a -> new String[]{null, "Attack", null, null, null});
		comp.put("getSize", a -> size);
		comp.put("getName", a -> name);
		NPCComposition composition = proxy(NPCComposition.class, comp);
		WorldPoint sw = new WorldPoint(BASE_X + x, BASE_Y + y, 0);
		Map<String, Function<Object[], Object>> n = new HashMap<>();
		n.put("getName", a -> name);
		n.put("isDead", a -> dead);
		n.put("getComposition", a -> composition);
		n.put("getTransformedComposition", a -> composition);
		n.put("getWorldLocation", a -> sw);
		n.put("getWorldArea", a -> new WorldArea(sw, size, size));
		n.put("getWorldView", a -> view);
		n.put("toString", a -> name + "@" + x + "," + y + "/" + size);
		NPC npc = proxy(NPC.class, n);
		npcs.add(npc);
		return npc;
	}

	void addMany(String name, int x, int y, int count)
	{
		for (int i = 0; i < count; i++)
		{
			add(name, x, y, 1);
		}
	}

	/** Puts the local player on (x,y) of the scene. Without it there is no local player. */
	void player(int x, int y)
	{
		WorldPoint at = new WorldPoint(BASE_X + x, BASE_Y + y, 0);
		Map<String, Function<Object[], Object>> p = new HashMap<>();
		p.put("getWorldLocation", a -> at);
		p.put("getWorldArea", a -> new WorldArea(at, 1, 1));
		p.put("getWorldView", a -> view);
		p.put("getName", a -> "player");
		player = proxy(Player.class, p);
	}

	BarrageIndicatorConfig config()
	{
		return new BarrageIndicatorConfig()
		{
			@Override
			public boolean onlyTask()
			{
				return onlyTask;
			}

			@Override
			public boolean countOthers()
			{
				return countOthers;
			}

			@Override
			public boolean onlyAncientsOrChins()
			{
				return onlyAncients;
			}

			@Override
			public boolean onlyMulti()
			{
				return onlyMulti;
			}

			@Override
			public String extraNames()
			{
				return extraNames;
			}

			@Override
			public int minimum()
			{
				return minimum;
			}
		};
	}

	Client client()
	{
		Map<String, Function<Object[], Object>> c = new HashMap<>();
		c.put("getTopLevelWorldView", a -> view);
		c.put("getLocalPlayer", a -> player);
		c.put("getVarbitValue", a ->
		{
			int id = (Integer) a[0];
			if (id == VarbitID.SPELLBOOK)
			{
				return spellbook;
			}
			if (id == VarbitID.MULTIWAY_INDICATOR)
			{
				return multi;
			}
			return 0;
		});
		c.put("getVarpValue", a ->
		{
			int id = (Integer) a[0];
			if (id == VarPlayerID.SLAYER_COUNT)
			{
				return taskLeft;
			}
			return id == VarPlayerID.COM_MODE ? attackStyle : 0;
		});
		c.put("getItemContainer", a ->
		{
			if ((Integer) a[0] != InventoryID.WORN || weapon < 0)
			{
				return null;
			}
			Item item = new Item(weapon, 1);
			Map<String, Function<Object[], Object>> worn = new HashMap<>();
			worn.put("getItem", b -> (Integer) b[0] == EquipmentInventorySlot.WEAPON.getSlotIdx() ? item : null);
			return proxy(ItemContainer.class, worn);
		});
		return proxy(Client.class, c);
	}

	/** One game tick of the plugin in this world: what it would draw. */
	List<BarrageIndicatorPlugin.Pile> run() throws Exception
	{
		// the task name is the one RuneLite's Slayer plugin saves in the profile
		BarrageIndicatorPlugin plugin = new BarrageIndicatorPlugin()
		{
			@Override
			String slayerTask()
			{
				return task;
			}
		};
		set(plugin, "client", client());
		set(plugin, "config", config());
		plugin.onGameTick(new GameTick());
		lastPlugin = plugin;
		return plugin.piles();
	}

	/** The pile drawn on the tile (x,y) of the scene, or null. */
	static BarrageIndicatorPlugin.Pile at(List<BarrageIndicatorPlugin.Pile> piles, int x, int y)
	{
		for (BarrageIndicatorPlugin.Pile p : piles)
		{
			WorldPoint w = p.npc.getWorldLocation();
			if (w.getX() == BASE_X + x && w.getY() == BASE_Y + y)
			{
				return p;
			}
		}
		return null;
	}

	/** The piles as text, "(x,y)=hits", a star on the best. */
	static String show(List<BarrageIndicatorPlugin.Pile> piles)
	{
		StringBuilder sb = new StringBuilder("[");
		for (BarrageIndicatorPlugin.Pile p : piles)
		{
			WorldPoint w = p.npc.getWorldLocation();
			sb.append(" (").append(w.getX() - BASE_X).append(',').append(w.getY() - BASE_Y).append(")=")
				.append(p.hits).append(p.best ? "*" : "");
		}
		return sb.append(" ]").toString();
	}

	static void set(Object target, String field, Object value) throws Exception
	{
		Field f = BarrageIndicatorPlugin.class.getDeclaredField(field);
		f.setAccessible(true);
		f.set(target, value);
	}

	private static Object zero(Class<?> t)
	{
		if (!t.isPrimitive() || t == void.class)
		{
			return null;
		}
		if (t == boolean.class)
		{
			return false;
		}
		if (t == long.class)
		{
			return 0L;
		}
		if (t == double.class)
		{
			return 0d;
		}
		if (t == float.class)
		{
			return 0f;
		}
		return 0;
	}

	@SuppressWarnings("unchecked")
	static <T> T proxy(Class<T> type, Map<String, Function<Object[], Object>> impl)
	{
		return (T) Proxy.newProxyInstance(type.getClassLoader(), new Class<?>[]{type}, (p, m, a) ->
		{
			Function<Object[], Object> f = impl.get(m.getName());
			if (f != null)
			{
				return f.apply(a);
			}
			switch (m.getName())
			{
				case "hashCode":
					return System.identityHashCode(p);
				case "equals":
					return p == a[0];
				case "toString":
					return type.getSimpleName();
				default:
					return zero(m.getReturnType());
			}
		});
	}
}
